function StepMark({ size = 1 }) {
  const heights = [8, 13, 18].map((h) => h * size);
  const colors = ["var(--teal)", "var(--gold)", "var(--red)"];
  return (
    <div className="flex items-end gap-[3px]" aria-hidden="true">
      <span style={{ width: 5 * size, height: heights[0], background: colors[0], borderRadius: 1 }} />
      <span style={{ width: 5 * size, height: heights[1], background: colors[1], borderRadius: 1 }} />
      <span style={{ width: 5 * size, height: heights[2], background: colors[2], borderRadius: 1 }} />
    </div>
  );
}

