/* ---------------------------- AAA AI ---------------------------- */

function StepBlock({ text, index }) {
  const h = 10 + index * 5;
  const colors = ["var(--teal)", "var(--gold)", "var(--red)"];
  return (
    <div className="flex gap-2.5 py-1.5">
      <div className="flex flex-col items-center pt-0.5 shrink-0">
        <div style={{ width: 5, height: h, background: colors[index % 3], borderRadius: 1 }} />
      </div>
      <p className="text-sm leading-relaxed" style={{ color: "var(--ink)" }}>{text}</p>
    </div>
  );
}

function formatAIMessage(text) {
  const lines = text.split("\n").filter((l) => l.trim() !== "");
  const stepLines = [];
  const otherLines = [];
  lines.forEach((line) => {
    if (/^step\s*\d+[:.]/i.test(line.trim())) stepLines.push(line.trim());
    else otherLines.push(line.trim());
  });
  if (stepLines.length === 0) {
    return <p className="text-sm leading-relaxed whitespace-pre-wrap" style={{ color: "var(--ink)" }}>{text}</p>;
  }
  return (
    <div>
      {otherLines.length > 0 && (
        <p className="text-sm leading-relaxed mb-1" style={{ color: "var(--ink)" }}>{otherLines.join(" ")}</p>
      )}
      {stepLines.map((s, i) => <StepBlock key={i} text={s} index={i} />)}
    </div>
  );
}

function AIView({ messages, onSend, loading, error, input, setInput, pendingImage, setPendingImage }) {
  const endRef = useRef(null);
  const fileInputRef = useRef(null);
  const recognitionRef = useRef(null);
  const [recording, setRecording] = useState(false);
  const [voiceUnsupported, setVoiceUnsupported] = useState(false);

  useEffect(() => { endRef.current?.scrollIntoView({ behavior: "smooth" }); }, [messages, loading]);

  const toggleRecording = () => {
    if (!SpeechRecognitionAPI) { setVoiceUnsupported(true); return; }
    if (recording) { recognitionRef.current?.stop(); return; }
    const recognition = new SpeechRecognitionAPI();
    recognition.lang = "en-US";
    recognition.interimResults = false;
    recognition.maxAlternatives = 1;
    recognition.onresult = (e) => {
      const transcript = e.results[0][0].transcript;
      setInput((prev) => (prev ? `${prev} ${transcript}` : transcript));
    };
    recognition.onend = () => setRecording(false);
    recognition.onerror = () => setRecording(false);
    recognitionRef.current = recognition;
    recognition.start();
    setRecording(true);
  };

  const handleImagePick = (e) => {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => setPendingImage({ dataUrl: reader.result, mediaType: file.type || "image/jpeg" });
    reader.readAsDataURL(file);
  };

  const triggerImagePick = () => fileInputRef.current?.click();

  return (
    <div className="pb-6 flex flex-col" style={{ minHeight: "70vh" }}>
      <SectionHeading eyebrow="Your personal academic assistant" title="AAA AI" />

      {messages.length <= 1 && (
        <div className="grid grid-cols-2 gap-2 mb-4">
          {QUICK_PROMPTS.map((q) => (
            <button key={q.label}
              onClick={() => (q.text === "__IMAGE__" ? triggerImagePick() : setInput(q.text))}
              className="text-left text-xs font-medium px-3 py-2.5 rounded-xl border" style={{ borderColor: "var(--line)", color: "var(--ink)", background: "var(--card)" }}>
              {q.label}
            </button>
          ))}
        </div>
      )}

      <div className="flex-1 space-y-3">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === "user" ? "justify-end" : "justify-start"}`}>
            <div className="max-w-[85%] rounded-2xl px-4 py-3"
                 style={m.role === "user" ? { background: "var(--teal-deep)", color: "#fff" } : { background: "var(--card)", border: "1px solid var(--line)" }}>
              {m.image && <img src={m.image} alt="Submitted" className="rounded-lg mb-2 max-h-48 object-cover" />}
              {m.role === "user"
                ? <p className="text-sm leading-relaxed whitespace-pre-wrap">{m.content}</p>
                : formatAIMessage(m.content)}
            </div>
          </div>
        ))}
        {loading && (
          <div className="flex items-center gap-2 text-xs" style={{ color: "var(--muted)" }}>
            <Loader2 size={14} className="animate-spin" /> AAA AI is thinking…
          </div>
        )}
        {error && (
          <div className="flex items-start gap-2 text-xs rounded-xl px-3 py-2.5" style={{ background: "#FBEAEA", color: "#9B2C2C" }}>
            <AlertCircle size={15} className="shrink-0 mt-0.5" />
            <span>Something went wrong reaching AAA AI. Please check your internet connection and try again.</span>
          </div>
        )}
        {voiceUnsupported && (
          <div className="flex items-start gap-2 text-xs rounded-xl px-3 py-2.5" style={{ background: "#FBEAEA", color: "#9B2C2C" }}>
            <AlertCircle size={15} className="shrink-0 mt-0.5" />
            <span>Voice input isn't supported in this browser — Chrome on Android or desktop works best.</span>
          </div>
        )}
        <div ref={endRef} />
      </div>

      {pendingImage && (
        <div className="mt-3 flex items-center gap-2">
          <img src={pendingImage.dataUrl} alt="To send" className="w-14 h-14 object-cover rounded-lg border" style={{ borderColor: "var(--line)" }} />
          <button onClick={() => setPendingImage(null)} className="flex items-center gap-1 text-xs font-medium px-2.5 py-1.5 rounded-lg border" style={{ borderColor: "var(--line)", color: "var(--muted)" }}>
            <X size={13} /> Remove
          </button>
        </div>
      )}

      <div className="sticky bottom-[64px] mt-3 flex items-center gap-1.5 rounded-2xl border p-1.5" style={{ background: "var(--card)", borderColor: "var(--line)" }}>
        <input ref={fileInputRef} type="file" accept="image/*" capture="environment" className="hidden" onChange={handleImagePick} />
        <button onClick={triggerImagePick} className="w-9 h-9 rounded-xl flex items-center justify-center shrink-0" style={{ background: "var(--teal-tint)" }} aria-label="Attach a photo">
          <Camera size={16} style={{ color: "var(--teal-deep)" }} />
        </button>
        <button onClick={toggleRecording}
          className="w-9 h-9 rounded-xl flex items-center justify-center shrink-0"
          style={{ background: recording ? "var(--red)" : "var(--teal-tint)" }} aria-label="Voice input">
          {recording ? <Square size={14} color="#fff" /> : <Mic size={16} style={{ color: "var(--teal-deep)" }} />}
        </button>
        <input
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => { if (e.key === "Enter" && (input.trim() || pendingImage) && !loading) onSend(); }}
          placeholder={recording ? "Listening…" : "Ask a question…"}
          className="flex-1 min-w-0 text-sm px-2 py-2 outline-none bg-transparent"
          style={{ color: "var(--ink)" }}
        />
        <button onClick={() => (input.trim() || pendingImage) && !loading && onSend()}
          className="w-9 h-9 rounded-xl flex items-center justify-center shrink-0"
          style={{ background: "var(--teal-deep)" }} aria-label="Send message">
          <Send size={15} color="#fff" />
        </button>
      </div>
    </div>
  );
}

